const XLSX = require("xlsx");
const fs = require("fs");
const path = require("path");

// Read the Excel file
const wb = XLSX.readFile(path.join(__dirname, "../testbed/data/order_summary.xlsx"));
const data = XLSX.utils.sheet_to_json(wb.Sheets["Orders"]);

// Filter confirmed orders
const confirmed = data.filter((row) => row.Status === "confirmed");

// Build the output text
const lines = [];
lines.push("Confirmed Orders Report");
lines.push("=" .repeat(90));
lines.push(
  `Generated: ${new Date().toISOString().slice(0, 19).replace("T", " ")}`
);
lines.push(
  `Total confirmed orders: ${confirmed.length} (out of ${data.length} total)`
);
lines.push("");
lines.push(
  "Order ID      | Customer                | Date       | Items                                                        | Total Paid"
);
lines.push("-".repeat(140));

for (const row of confirmed) {
  const orderId = String(row["Order ID"]).padEnd(13);
  const customer = String(row["Customer"]).padEnd(23);
  const date = String(row["Date"]).padEnd(10);
  const items = String(row["Items"]).padEnd(60);
  const total = `$${row["Total Paid"]}`;
  lines.push(`${orderId} | ${customer} | ${date} | ${items} | ${total}`);
}

lines.push("-".repeat(140));

// Calculate grand total
const grandTotal = confirmed.reduce((sum, r) => sum + r["Total Paid"], 0);
lines.push(`\nGrand Total: $${grandTotal}`);

// Write to file
const outputPath = path.join(__dirname, "../data/confirmed_orders.txt");
fs.writeFileSync(outputPath, lines.join("\n") + "\n", "utf-8");
console.log(`✅ Saved ${confirmed.length} confirmed orders to: ${outputPath}`);

